#pragma once
#include "ksPartModulationTask.h"
#include "ksVoiceRefreshTask.h"
#include "ksOscillatorModulationTask.h"
#include "ksOscillatorPitchTask.h"
#include "ksGlobalModulationTask.h"
#include "ksPartControlTasks.h"
